const { Client } = require('pg');
const id = String(($json.query || {}).id || '');
if(!id) return [{ json: { _status:200, _body:{ ok:true, data:{ valido:false } } } }];
const client = new Client({host:'postgres',port:5432,user:'yavibot',password:'yavibot_dev_2026',database:'yavibot'});
await client.connect();
try {
  const r = (await client.query(
    `SELECT e.nombres, to_char(c.fecha,'DD/MM/YYYY') AS fecha
     FROM qr_codigos q JOIN certificados c ON c.id = q.certificado_id
     JOIN estudiantes e ON e.id = q.estudiante_id WHERE q.identificador = $1`, [id])).rows[0];
  if(!r) return [{ json: { _status:200, _body:{ ok:true, data:{ valido:false } } } }];
  await client.query('UPDATE qr_codigos SET verificaciones = verificaciones + 1 WHERE identificador = $1', [id]);
  // Privacidad: solo nombres + inicial del apellido
  const partes = r.nombres.trim().split(/\s+/);
  const visible = partes.length > 1 ? partes[0] + ' ' + partes[partes.length-1][0] + '.' : partes[0];
  return [{ json: { _status:200, _body:{ ok:true, data:{ valido:true, estudiante: visible, tipo:'Certificado de Matrícula', fecha: r.fecha } } } }];
} finally { await client.end(); }
